import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { LIBRARY_EXERCISES } from '../../data/exerciseLibrary';
import {
  BUILT_IN_EXERCISES,
  CORE_EXERCISES,
  EQUIPMENT_ORDER,
  KIND_LABELS,
  MUSCLE_GROUP_ORDER,
} from '../../data/workoutExercises';
import { EXERCISE_DEMOS } from '../../data/exerciseDemos';

// The 200 library exercises (content/exercise-library/), generated by
// scripts/importExerciseLibrary.ts. Ids are permanent once shipped.

const ROOT = join(__dirname, '../../..');
// Read as text: jest can't load the jpg require()s in the images file itself.
const imagesFile = readFileSync(join(ROOT, 'src/data/exerciseLibraryImages.ts'), 'utf8');

describe('the exercise library', () => {
  it('has 200 exercises with unique ids that never clash with the core', () => {
    expect(LIBRARY_EXERCISES).toHaveLength(200);
    const ids = LIBRARY_EXERCISES.map((e) => e.id);
    expect(new Set(ids).size).toBe(ids.length);
    const core = new Set(CORE_EXERCISES.map((e) => e.id));
    expect(ids.filter((id) => core.has(id))).toEqual([]);
  });

  it('uses url-safe ids, and no name twice across all built-ins', () => {
    expect(LIBRARY_EXERCISES.filter((e) => !/^[a-z0-9]+(-[a-z0-9]+)*$/.test(e.id)).map((e) => e.id)).toEqual([]);
    const names = BUILT_IN_EXERCISES.map((e) => e.name.toLowerCase());
    expect(names.filter((n, i) => names.indexOf(n) !== i)).toEqual([]);
  });

  it('only uses muscles, equipment and kinds the app knows', () => {
    const bad = LIBRARY_EXERCISES.filter(
      (e) =>
        !MUSCLE_GROUP_ORDER.includes(e.muscle) ||
        !EQUIPMENT_ORDER.includes(e.equipment!) ||
        !(e.kind in KIND_LABELS) ||
        e.kind === 'distance'
    );
    expect(bad.map((e) => e.id)).toEqual([]);
  });

  it('gives every exercise steps, without the boilerplate "Repeat…" line', () => {
    expect(LIBRARY_EXERCISES.filter((e) => e.steps.length === 0).map((e) => e.id)).toEqual([]);
    const boiler = LIBRARY_EXERCISES.filter((e) => e.steps.some((s) => /^repeat for the recommended/i.test(s)));
    expect(boiler.map((e) => e.id)).toEqual([]);
  });

  it('bundles a start and an end photo for every exercise', () => {
    const missing = LIBRARY_EXERCISES.flatMap((e) =>
      ['start', 'end']
        .map((frame) => `assets/exercise-library/${e.id}_${frame}.jpg`)
        .filter((file) => !existsSync(join(ROOT, file)) || !imagesFile.includes(`'../../${file}'`))
    );
    expect(missing).toEqual([]);
  });

  it('leaves the core’s hand-written demos to the core', () => {
    expect(LIBRARY_EXERCISES.filter((e) => EXERCISE_DEMOS[e.id]).map((e) => e.id)).toEqual([]);
  });

  it('strips the library-only fields from the built-in list', () => {
    const lib = BUILT_IN_EXERCISES.find((e) => e.id === 'db-bench-press') as unknown as Record<string, unknown>;
    expect(lib).toBeDefined();
    expect(lib.steps).toBeUndefined();
    expect(lib.sourceId).toBeUndefined();
  });
});
